    best_vector = None
    maximum = {
        name: max([-1] + [row['version'] for row in rows
                          if isinstance(row, dict) and isinstance(row.get('version'), int)])
        for name, rows in packages.items()
    }

    def visit(chosen, active, constraints):
        nonlocal best, best_vector
        upper = [chosen[n] if n in chosen else maximum.get(n, -1) for n in names]
        if best_vector is not None and upper <= best_vector:
            return

        pending = sorted(active - chosen.keys())
        if not pending:
            vector = [chosen.get(n, -1) for n in names]
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = dict(chosen)
            return

        name = pending[0]
        rows = packages.get(name, [])
        for row in rows:
            if not isinstance(row, dict) or not isinstance(row.get('version'), int):
                continue
            version = row['version']
            if not satisfies(version, constraints.get(name, [])):
                continue

            next_chosen = dict(chosen)
            next_chosen[name] = version
            next_active = set(active)
            next_constraints = {key: list(value) for key, value in constraints.items()}
            valid = True
            deps = row.get('deps', [])
            if not isinstance(deps, list):
                continue
            for item in deps:
                parsed = dependency(item)
