                dep_name, dep_bound = parsed
                if dep_name not in packages:
                    valid = False
                    break
                next_active.add(dep_name)
                if dep_bound is not None:
                    next_constraints.setdefault(dep_name, []).append(dep_bound)
                if dep_name in next_chosen and not satisfies(
                        next_chosen[dep_name], next_constraints.get(dep_name, [])):
                    valid = False
                    break
            if valid:
                visit(next_chosen, next_active, next_constraints)

    visit({}, set(roots), limits)
    return {'versions': best if best is not None else {}}
